mapper.select:
SELECT NVL(MAX(t1.GIJUN_RT), 0)
  FROM SYX1HY t1
 WHERE t1.CORP_GR   = #{corpGr}
   AND t1.GIJUN_YMD = #{trYmd}
   AND t1.CURRENCY  = 'USD'

mapper.update:
UPDATE SZT0IA_V
   SET JM_PER         = #{jmPer}
     , USD_WONBON_AEK = #{usdWonbonAek}
 WHERE CORP_GR        = #{corpGr}
   AND TR_YMD         = TO_DATE(#{trYmd}, 'YYYY-MM-DD')
   AND FUND_CD        = #{fundCd}

UPDATE SZT0IA_V
   SET DEL     = 'Y'
 WHERE CORP_GR = #{corpGr}
   AND TR_YMD  = #{trYmd}
   AND FUND_CD = #{fundCd}

